"""Adversarial finite benchmark checks; no reference generated by evaluated code."""
import copy
import json
from pathlib import Path
import subprocess
import sys
import unittest
from unittest.mock import patch
sys.path.insert(0, str(Path(__file__).resolve().parents[1] / 'scripts'))
import accounting_benchmark_v1 as b


class References(unittest.TestCase):
    @classmethod
    def setUpClass(cls):
        cls.fixture = b.read(b.ROOT / b.FIXTURE)

    def test_source_hashes_locators_and_schema(self):
        b.validate_fixture(self.fixture)

    def test_denominator_cannot_drift(self):
        f = copy.deepcopy(self.fixture); f['protocol']['chronology_denominator'] = 11
        with self.assertRaises(ValueError): b.validate_fixture(f)

    def test_duplicate_reference_rejected(self):
        f = copy.deepcopy(self.fixture); f['chronology'][1]['id'] = f['chronology'][0]['id']
        with self.assertRaises(ValueError): b.validate_fixture(f)

    def test_bad_manual_arithmetic_rejected(self):
        f = copy.deepcopy(self.fixture); f['chronology'][0]['expected']['amount'] = '9'
        with self.assertRaises(ValueError): b.validate_fixture(f)

    def test_source_quote_tamper_rejected(self):
        f = copy.deepcopy(self.fixture); f['source_references'][0]['supports'][0]['quote'] = 'wrong'
        with self.assertRaises(ValueError): b.validate_fixture(f)

    def test_unknown_is_not_invented_answer(self):
        r = self.fixture['source_references'][3]
        self.assertTrue(b.admit_source_answer(r, 'unresolved'))
        self.assertFalse(b.admit_source_answer(r, '14575000000 USD of effective floating-rate debt'))
        self.assertFalse(b.admit_source_answer(r, None))

    def test_exposure_and_dependent_test_families(self):
        e = b.exposure_register()
        self.assertEqual(e['issuer_count'], 9)
        self.assertEqual({r['issuer'] for r in e['families'] if r['proposed_role']=='test_candidate'}, {'jpmorgan','ping_an','munich_re'})
        self.assertTrue(all(r['source_acquisition_qa_exposure'] and not r['clean_heldout'] for r in e['families']))
        self.assertEqual(e['window']['years_inclusive'], 8)

    def test_preparation_tamper(self):
        d = b.preparation(); b.verify_preparation(d)
        d['preparation']['references']['chronology'][0]['expected']['amount'] = '100'
        with self.assertRaisesRegex(ValueError, 'preparation hash'): b.verify_preparation(d)

    def test_changed_reference_hash(self):
        d = b.preparation(); d['preparation']['reference_sha256'] = '0'*64
        d['preparation_sha256'] = b.digest(d['preparation'])
        with self.assertRaisesRegex(ValueError, 'reference hash'): b.verify_preparation(d)

    def test_changed_file_pin(self):
        d = b.preparation(); d['preparation']['input_hashes'][b.FIXTURE] = '0'*64
        d['preparation_sha256'] = b.digest(d['preparation'])
        with self.assertRaisesRegex(ValueError, 'frozen input'): b.verify_preparation(d)


class Chronology(unittest.TestCase):
    def setUp(self):
        self.cases = b.read(b.ROOT / b.FIXTURE)['chronology']
        self.answers = [{'id': c['id'], 'answer': copy.deepcopy(c['expected'])} for c in self.cases]

    def test_evaluated_component_matches_independent_references(self):
        result = b.score_chronology(self.cases, b.evaluate_chronology(self.cases))
        self.assertTrue(result['all_passed'], result)
        self.assertEqual(result['by_kind'], {'valid': {'denominator':3,'passed':3}, 'invalid': {'denominator':9,'passed':9}})

    def test_correct(self):
        self.assertTrue(b.score_chronology(self.cases,self.answers)['all_passed'])

    def test_missing_not_excluded(self):
        result=b.score_chronology(self.cases,self.answers[:-1])
        self.assertEqual((result['denominator'],result['passed']),(12,11))

    def test_extra(self):
        self.answers.append({'id':'extra','answer':{}})
        self.assertFalse(b.score_chronology(self.cases,self.answers)['all_passed'])

    def test_duplicate(self):
        self.answers.append(self.answers[0])
        self.assertEqual(b.score_chronology(self.cases,self.answers)['passed'],11)

    def test_malformed(self):
        self.answers[0]=None
        self.assertFalse(b.score_chronology(self.cases,self.answers)['all_passed'])
        self.assertEqual(b.score_chronology(self.cases,None)['passed'],0)

    def test_wrong_amount_context_period_and_code(self):
        for key,value in [('amount','0'),('context',{}),('period',{'start':'2024-04-02','end':'2024-07-01'})]:
            a=copy.deepcopy(self.answers); a[0]['answer'][key]=value
            self.assertEqual(b.score_chronology(self.cases,a)['passed'],11)
        self.answers[-1]['answer']['code']='CONTEXT_MISMATCH'
        self.assertEqual(b.score_chronology(self.cases,self.answers)['passed'],11)

    def test_unexpected_rejection_abstention_crash_timeout(self):
        for status in ['rejected','abstain','crash','timeout']:
            a=copy.deepcopy(self.answers); a[0]['answer']={'status':status}
            self.assertEqual(b.score_chronology(self.cases,a)['passed'],11)


class Workloads(unittest.TestCase):
    @classmethod
    def setUpClass(cls):
        cls.cells=b.read(b.ROOT/b.FIXTURE)['workloads']
        cls.observations=[b.execute_workload(c) for c in cls.cells]
        cls.refs=[{**c,'independent_oracle':b.independent_enumeration(c)} for c in cls.cells]

    def test_complete_partial_and_unsupported(self):
        for c,o in zip(self.refs,self.observations):
            self.assertTrue(b.score_workload(c,o)['passed'], b.score_workload(c,o))
        self.assertEqual(self.observations[3]['result']['coverage']['unresolved'],30)
        self.assertEqual(self.observations[4]['result']['status'],'UnsupportedFragment')

    def test_independent_feasible_sets_nontrivial(self):
        self.assertEqual([sum(r['feasible'] for r in c['independent_oracle']) for c in self.refs[:3]],[1,5,16])

    def test_omitted_branch_rejected(self):
        o=copy.deepcopy(self.observations[2]);o['result']['cells'].pop()
        self.assertFalse(b.score_workload(self.refs[2],o)['passed'])

    def test_fabricated_output_rejected(self):
        o=copy.deepcopy(self.observations[1]);o['result']['cells'][0]['outputs']['weighted_sum']='999'
        self.assertFalse(b.score_workload(self.refs[1],o)['passed'])

    def test_false_complete_rejected(self):
        o=copy.deepcopy(self.observations[3]);o['result']['coverage'].update(complete=True,unresolved=0)
        self.assertFalse(b.score_workload(self.refs[3],o)['passed'])

    def test_missing_measurements_rejected(self):
        for key in b.MEASUREMENTS:
            o=copy.deepcopy(self.observations[0]);del o['metrics'][key]
            self.assertFalse(b.score_workload(self.refs[0],o)['passed'],key)

    def test_missing_reply_rejected(self):
        self.assertFalse(b.score_workload(self.refs[0],{})['passed'])

    def test_child_timeout_and_crash(self):
        def timeout(*args,**kwargs): raise subprocess.TimeoutExpired(args[0],1)
        self.assertEqual(b.run_child(self.cells[0],1,timeout)['failure'],'timeout')
        def crash(*args,**kwargs): return subprocess.CompletedProcess(args[0],1,'','deliberate test failure')
        self.assertEqual(b.run_child(self.cells[0],1,crash)['failure'],'child_exit')


if __name__=='__main__': unittest.main()
